class GiscusCommentManager{constructor(){this.setupMessageListener()}setupMessageListener(){window.addEventListener("message",e=>{if(e.origin!=="https://giscus.app")return;if(typeof e.data!="object"||!e.data.giscus)return;const n=e.data.giscus,t=window.location.pathname;if("discussion"in n){const e=n.discussion;if(e&&typeof e.totalCommentCount=="number"){const n=e.totalCommentCount||0,s=e.totalReplyCount||0,o=n+s;this.updateCommentCountDisplays(t,o),console.log(`Giscus: Page ${t} has ${n} comments and ${s} replies (${o} total)`)}else e===null&&(this.updateCommentCountDisplays(t,0),console.log(`Giscus: Page ${t} has no discussion (defaulting to 0 comments)`))}if("error"in n){const e=n.error;this.updateCommentCountDisplays(t,0)}})}updateCommentCountDisplays(e,t){const n=document.querySelectorAll(`[data-url="${e}"]`);n.forEach(e=>{const n=e.querySelector("a")||e;t===0?n.innerHTML="0 comments":t===1?n.innerHTML="1 comment":n.innerHTML=`${t} comments`})}initialize(){}}document.addEventListener("DOMContentLoaded",function(){window.giscusCommentManager=new GiscusCommentManager,window.giscusCommentManager.initialize()})